    cur.execute("SELECT name FROM products WHERE sku = ?", (sku,))
    return cur.fetchone()

def split_into_weeks(days, start_weekday=0):
    weeks, week = [], []
    for day in days:
        week.append(day)
        if (day.weekday() - start_weekday) % 7 == 6:
            weeks.append(week)
            week = []
    if week:
        weeks.append(week)
    return weeks

def truncate_middle(text, limit):
    if limit < 5:
        raise ValueError("limit too small")
    if len(text) <= limit:
        return text
    keep = limit - 3
    head = keep - keep // 2
    return text[:head] + "..." + text[len(text) - keep // 2:]

def pick_by_weight(weights, point):
    total = sum(weights)
    if total <= 0:
        raise ValueError("weights must add up to more than zero")
    target = (point % 1) * total
    running = 0
    for index, weight in enumerate(weights):
        running += weight
        if target < running:
            return index
    return len(weights) - 1

def longest_streak(flags):
    best = current = 0
    end = -1
    for i, flag in enumerate(flags):
        current = current + 1 if flag else 0
        if current > best:
            best, end = current, i
    return best, end - best + 1 if best else None

def round_robin(lists):
    iterators = [iter(l) for l in lists]
    out = []
    while iterators:
        for it in list(iterators):
            try:
                out.append(next(it))
            except StopIteration:
                iterators.remove(it)
    return out

def parse_settings(text):
    result = {}
    for number, line in enumerate(text.splitlines(), start=1):
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        key, sep, value = line.partition("=")
        if not sep:
            raise ValueError(f"line {number}: expected key=value")
        result[key.strip()] = value.strip()
    return result

def pack_batches(items, limit, size_of=len):
    batches, current, used = [], [], 0
    for item in items:
        size = size_of(item)
        if current and used + size > limit:
            batches.append(current)
            current, used = [], 0
        current.append(item)
        used += size
    if current:
        batches.append(current)
    return batches

def valid_isbn10(text):
    digits = text.replace("-", "")
    if len(digits) != 10:
        return False
    total = 0
    for i, ch in enumerate(digits):
        value = 10 if (ch in "xX" and i == 9) else int(ch) if ch.isdigit() else -1
        if value < 0:
            return False
        total += value * (10 - i)
    return total % 11 == 0

def compare_versions(a, b):
    pa = [int(x) for x in a.split(".")]
    pb = [int(x) for x in b.split(".")]
    length = max(len(pa), len(pb))
    pa += [0] * (length - len(pa))
    pb += [0] * (length - len(pb))
    for x, y in zip(pa, pb):
        if x != y:
            return -1 if x < y else 1
    return 0

def instant_runoff(ballots, candidates):
    remaining = set(candidates)
    while remaining:
        tally = {c: 0 for c in remaining}
        for ballot in ballots:
            for choice in ballot:
                if choice in remaining:
                    tally[choice] += 1
                    break
        total = sum(tally.values())
        leader = max(tally, key=tally.get)
        if total and tally[leader] * 2 > total:
            return leader
        remaining.discard(min(tally, key=tally.get))
    return None

def pack_tags(tags, width):
    lines, line = [], ""
    for tag in tags:
        label = "#" + tag
        if line and len(line) + 1 + len(label) > width:
            lines.append(line)
            line = label
        else:
            line = f"{line} {label}".strip()
    if line:
        lines.append(line)
    return lines

def rate_summary(timestamps, now, windows=(60, 300, 3600)):
    ordered = sorted(timestamps, reverse=True)
    summary = {}
    for window in windows:
        count = 0
        for t in ordered:
            if now - t > window:
                break
            count += 1
        summary[window] = {"count": count, "per_minute": round(count * 60 / window, 2)}
    return summary

def find_conflicts(events):
    ordered = sorted(events, key=lambda e: (e["start"], e["end"]))
    conflicts = []
    active = []
    for event in ordered:
        active = [a for a in active if a["end"] > event["start"]]
        for other in active:
            conflicts.append((other["id"], event["id"]))
        active.append(event)
    return conflicts

def rescale(values, low=0.0, high=100.0):
    if not values:
        return []
    smallest, largest = min(values), max(values)
    if smallest == largest:
        return [(low + high) / 2 for _ in values]
    span = largest - smallest
    return [low + (v - smallest) / span * (high - low) for v in values]

def parse_filters(text):
    operators = (">=", "<=", "!=", "=", ">", "<")
    filters = []
    for part in text.split(","):
        part = part.strip()
        if not part:
            continue
        for op in operators:
            name, found, value = part.partition(op)
            if found:
                filters.append({"field": name.strip(), "op": op, "value": value.strip()})
                break
        else:
            raise ValueError("cannot parse filter: " + part)
    return filters

def common_free_slots(calendars, day_start, day_end, minimum):
    busy = []
    for calendar in calendars:
        busy.extend(calendar)
    busy.sort()
    merged = []
    for start, end in busy:
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    free = []
    cursor = day_start
    for start, end in merged:
        if start - cursor >= minimum:
            free.append((cursor, start))
        cursor = max(cursor, end)
    if day_end - cursor >= minimum:
        free.append((cursor, day_end))
    return free

def validate_form(data, rules):
    errors = {}
    cleaned = {}
    for field, rule in rules.items():
        value = data.get(field)
        if value is None or value == "":
            if rule.get("required"):
                errors[field] = "required"
            elif "default" in rule:
                cleaned[field] = rule["default"]
            continue
        kind = rule.get("type", str)
        try:
            value = kind(value)
        except (TypeError, ValueError):
            errors[field] = "must be " + kind.__name__
            continue
        if "min" in rule and value < rule["min"]:
            errors[field] = f"must be at least {rule['min']}"
        elif "max" in rule and value > rule["max"]:
            errors[field] = f"must be at most {rule['max']}"
        elif "choices" in rule and value not in rule["choices"]:
            errors[field] = "not an allowed value"
        else:
            cleaned[field] = value
    return cleaned, errors

def order_tasks(tasks):
    dependents = {t["id"]: [] for t in tasks}
    waiting = {}
    for task in tasks:
        waiting[task["id"]] = len(task.get("needs", []))
        for need in task.get("needs", []):
            if need not in dependents:
                raise KeyError(need)
            dependents[need].append(task["id"])
    ready = sorted(t for t, n in waiting.items() if n == 0)
    order = []
    while ready:
        current = ready.pop(0)
        order.append(current)
        for nxt in dependents[current]:
            waiting[nxt] -= 1
            if waiting[nxt] == 0:
                ready.append(nxt)
                ready.sort()
    if len(order) != len(tasks):
        raise ValueError("tasks contain a cycle")
    return order

def fill_template(template, values, missing="?"):
    out, i = [], 0
    while i < len(template):
        if template.startswith("{{", i):
            out.append("{")
            i += 2
        elif template.startswith("}}", i):
            out.append("}")
            i += 2
        elif template[i] == "{":
            end = template.find("}", i)
            if end == -1:
                raise ValueError("unclosed placeholder")
            name = template[i + 1:end].strip()
            out.append(str(values.get(name, missing)))
            i = end + 1
        else:
            out.append(template[i])
            i += 1
    return "".join(out)

def simulate_cache(accesses, capacity):
    cache = {}
    order = []
    hits = misses = evictions = 0
    for key in accesses:
        if key in cache:
            hits += 1
            order.remove(key)
        else:
            misses += 1
            if len(cache) >= capacity:
                oldest = order.pop(0)
                del cache[oldest]
                evictions += 1
            cache[key] = True
        order.append(key)
    total = hits + misses
    return {"hits": hits, "misses": misses, "evictions": evictions, "hit_rate": round(hits / total, 3) if total else 0.0}

def render_tree(paths):
    tree = {}
    for path in paths:
        node = tree
        for part in [p for p in path.split("/") if p]:
            node = node.setdefault(part, {})
    lines = []

    def walk(node, prefix):
        names = sorted(node)
        for i, name in enumerate(names):
            last = i == len(names) - 1
            lines.append(prefix + ("`-- " if last else "|-- ") + name)
            walk(node[name], prefix + ("    " if last else "|   "))

    walk(tree, "")
    return lines

def summarize_requests(lines):
    stats = {"total": 0, "errors": 0, "bytes": 0, "slowest": None}
    by_status = {}
    by_path = {}
    for line in lines:
        parts = line.split()
        if len(parts) < 5:
            continue
        method, path, status, size, millis = parts[0], parts[1], int(parts[2]), int(parts[3]), float(parts[4])
        stats["total"] += 1
        stats["bytes"] += size
        by_status[status] = by_status.get(status, 0) + 1
        by_path[path] = by_path.get(path, 0) + 1
        if status >= 500:
            stats["errors"] += 1
        if stats["slowest"] is None or millis > stats["slowest"][1]:
            stats["slowest"] = (path, millis)
    top = sorted(by_path.items(), key=lambda kv: (-kv[1], kv[0]))[:5]
    stats["error_rate"] = round(stats["errors"] / stats["total"], 4) if stats["total"] else 0.0
    return {"stats": stats, "by_status": by_status, "top_paths": top}

def solve_grid(grid):
    def candidates(r, c):
        used = set(grid[r]) | {grid[i][c] for i in range(9)}
        br, bc = 3 * (r // 3), 3 * (c // 3)
        used |= {grid[br + i][bc + j] for i in range(3) for j in range(3)}
        return [n for n in range(1, 10) if n not in used]

    def find_empty():
        best, options = None, None
        for r in range(9):
            for c in range(9):
                if grid[r][c] == 0:
                    found = candidates(r, c)
                    if options is None or len(found) < len(options):
                        best, options = (r, c), found
                        if len(found) <= 1:
                            return best, options
        return best, options

    def search():
        cell, options = find_empty()
        if cell is None:
            return True
        r, c = cell
        for n in options:
            grid[r][c] = n
            if search():
                return True
            grid[r][c] = 0
        return False

    if len(grid) != 9 or any(len(row) != 9 for row in grid):
        raise ValueError("grid must be 9 by 9")
    if sum(1 for row in grid for v in row if v) < 17:
        raise ValueError("too few clues")
    for r in range(9):
        for c in range(9):
            v = grid[r][c]
            if v:
                grid[r][c] = 0
                if v not in candidates(r, c):
                    raise ValueError("clues conflict")
                grid[r][c] = v
    return grid if search() else None

def resolve_versions(requirements, available):
    if not isinstance(requirements, dict):
        raise TypeError("requirements must be a mapping")

    def parse(version):
        return tuple(int(x) for x in version.split("."))

    def satisfies(version, constraint):
        for op in (">=", "<=", "==", ">", "<"):
            if constraint.startswith(op):
                bound = parse(constraint[len(op):])
                current = parse(version)
                return {
                    ">=": current >= bound,
                    "<=": current <= bound,
                    "==": current == bound,
                    ">": current > bound,
                    "<": current < bound,
                }[op]
        raise ValueError("bad constraint: " + constraint)

    chosen = {}
    problems = []
    for name, constraints in sorted(requirements.items()):
        versions = sorted(available.get(name, []), key=parse, reverse=True)
        if not versions:
            problems.append(f"{name}: not available")
            continue
        for version in versions:
            if all(satisfies(version, c) for c in constraints):
                chosen[name] = version
                break
        else:
            problems.append(f"{name}: no version satisfies {', '.join(constraints)}")
    unused = sorted(set(available) - set(requirements))
    newest = {name: max(versions, key=parse) for name, versions in available.items() if versions}
    outdated = {name: (chosen[name], newest[name]) for name in chosen if chosen[name] != newest.get(name)}
    return {"chosen": chosen, "problems": problems, "unused": unused, "outdated": outdated, "ok": not problems}

