def parse_range_header(header, size):
    if not header.startswith("bytes="):
        raise ValueError("unsupported unit")
    ranges = []
    for part in header[6:].split(","):
        start, _, end = part.strip().partition("-")
        if start == "":
            first = max(size - int(end), 0)
            last = size - 1
        else:
            first = int(start)
            last = int(end) if end else size - 1
        if first > last or first >= size:
            raise ValueError("unsatisfiable range")
        ranges.append((first, min(last, size - 1)))
    return ranges

def next_run(last_run, interval_minutes, active_hours=(8, 18)):
    candidate = last_run + timedelta(minutes=interval_minutes)
    start, end = active_hours
    if candidate.hour >= end:
        candidate = (candidate + timedelta(days=1)).replace(hour=start, minute=0, second=0, microsecond=0)
    elif candidate.hour < start:
        candidate = candidate.replace(hour=start, minute=0, second=0, microsecond=0)
    while candidate.weekday() >= 5:
        candidate += timedelta(days=1)
    return candidate

def edit_script(a, b):
    table = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(len(a) + 1):
        for j in range(len(b) + 1):
            if i == 0 or j == 0:
                table[i][j] = i + j
            elif a[i - 1] == b[j - 1]:
                table[i][j] = table[i - 1][j - 1]
            else:
                table[i][j] = 1 + min(table[i - 1][j], table[i][j - 1], table[i - 1][j - 1])
    return table[len(a)][len(b)]

