def inventory_value(conn, warehouse=None, category=None):
    sql_text = (
        "SELECT p.category, COUNT(*) AS skus, SUM(s.qty) AS units, SUM(s.qty * p.cost) AS value "
        "FROM stock s JOIN products p ON p.sku = s.sku WHERE s.qty > 0"
    )
    params = []
    if warehouse:
        sql_text += " AND s.warehouse = %s"
        params.append(warehouse)
    if category:
        sql_text += " AND p.category = %s"
        params.append(category)
    sql_text += " GROUP BY p.category ORDER BY value DESC"
    with conn.cursor() as cur:
        cur.execute(sql_text, params)
        rows = cur.fetchall()
    total = sum(r[3] for r in rows)
    return {
        "total": float(total),
        "categories": [
            {"name": r[0], "skus": r[1], "units": r[2], "value": float(r[3]), "share": round(float(r[3]) / float(total), 3) if total else 0.0}
            for r in rows
        ],
    }

def generate_invoices(period_start, period_end, dry_run=False):
    created = []
    subscriptions = Subscription.objects.filter(active=True, next_billing__gte=period_start, next_billing__lt=period_end).select_related("customer", "plan")
    with transaction.atomic():
        for sub in subscriptions:
            if Invoice.objects.filter(subscription=sub, period_start=period_start).exists():
                continue
            amount = sub.plan.price * (Decimal("1.00") - sub.discount)
            invoice = Invoice(subscription=sub, customer=sub.customer, period_start=period_start, period_end=period_end, amount=amount)
            if not dry_run:
                invoice.save()
                sub.next_billing = period_end
                sub.save(update_fields=["next_billing"])
                InvoiceLine.objects.create(invoice=invoice, description=sub.plan.name, amount=amount)
            created.append(invoice)
        if dry_run:
            transaction.set_rollback(True)
    return {"count": len(created), "total": sum(i.amount for i in created)}

def balance_teams(players, teams=2):
    ranked = sorted(players, key=lambda p: p["skill"], reverse=True)
    groups = [{"members": [], "skill": 0} for _ in range(teams)]
    for player in ranked:
        target = min(groups, key=lambda g: (g["skill"], len(g["members"])))
        target["members"].append(player["name"])
        target["skill"] += player["skill"]
    spread = max(g["skill"] for g in groups) - min(g["skill"] for g in groups)
    return {"teams": [g["members"] for g in groups], "skills": [g["skill"] for g in groups], "spread": spread}

def audit_export(conn, filters, fmt="rows", limit=500):
    columns = {"actor": "actor", "action": "action", "target": "target"}
    clauses, params = [], []
    for name, value in filters.items():
        if name not in columns:
            raise ValueError("unsupported filter: " + name)
        if isinstance(value, (list, tuple)):
            clauses.append(f"{columns[name]} = ANY(%s)")
            params.append(list(value))
        else:
            clauses.append(f"{columns[name]} = %s")
            params.append(value)
    where = (" WHERE " + " AND ".join(clauses)) if clauses else ""
    limit = max(1, min(int(limit), 5000))
    with conn.cursor() as cur:
        cur.execute(f"SELECT at, actor, action, target FROM audit_log{where} ORDER BY at DESC LIMIT {limit}", params)
        rows = cur.fetchall()
    if fmt == "csv":
        return chr(10).join(",".join(str(c) for c in row) for row in rows)
    return [dict(zip(("at", "actor", "action", "target"), row)) for row in rows]

def retention_table(request):
    period = request.GET.get("period", "week")
    metric = request.GET.get("metric", "active")
    periods = {"day": "date_trunc('day', joined)", "week": "date_trunc('week', joined)", "month": "date_trunc('month', joined)"}
    metrics = {"active": "COUNT(DISTINCT user_id)", "events": "COUNT(*)"}
    if period not in periods or metric not in metrics:
        return JsonResponse({"error": "unsupported"}, status=400)
    with connection.cursor() as cursor:
        cursor.execute(
            f"SELECT {periods[period]} AS cohort, {metrics[metric]} FROM analytics_event WHERE joined >= %s GROUP BY cohort ORDER BY cohort",
            [request.GET.get("since", "2024-01-01")],
        )
        rows = cursor.fetchall()
    return JsonResponse({"period": period, "metric": metric, "rows": [{"cohort": str(c), "value": v} for c, v in rows]})

def find_by(self, **criteria):
    model = self.model
    conditions = []
    for key, value in criteria.items():
        column = getattr(model, key, None)
        if column is None or key not in self.searchable:
            raise ValueError("cannot search by " + key)
        if isinstance(value, (list, tuple, set)):
            conditions.append(column.in_(list(value)))
        elif isinstance(value, str) and "*" in value:
            conditions.append(column.like(value.replace("*", "%")))
        else:
            conditions.append(column == value)
    query = self.session.query(model)
    if conditions:
        query = query.filter(*conditions)
    if self.default_order is not None:
        query = query.order_by(self.default_order)
    return query.limit(self.max_rows).all()

@app.route("/api/orders/<int:order_id>", methods=["PATCH"])
def update_order(order_id):
    data = request.get_json() or {}
    action = data.get("action")
    actor = session.get("user_id")
    if actor is None:
        return jsonify(error="sign in first"), 401
    with get_conn() as conn, conn.cursor() as cur:
        cur.execute("SELECT status, customer_id, total FROM orders WHERE id = %s FOR UPDATE", (order_id,))
        row = cur.fetchone()
        if row is None:
            return jsonify(error="not found"), 404
        status, customer_id, total = row
        if action == "pay":
            if status != "new":
                return jsonify(error="order is not awaiting payment"), 409
            cur.execute("UPDATE orders SET status = 'paid', paid_at = now() WHERE id = %s", (order_id,))
            cur.execute("INSERT INTO payments (order_id, amount, method) VALUES (%s, %s, %s)", (order_id, total, data.get("method", "card")))
        elif action == "ship":
            if status != "paid":
                return jsonify(error="order is not paid"), 409
            carrier = data.get("carrier")
            tracking = data.get("tracking")
            if not carrier or not tracking:
                return jsonify(error="carrier and tracking are required"), 400
            cur.execute("UPDATE orders SET status = 'shipped', shipped_at = now() WHERE id = %s", (order_id,))
            cur.execute("INSERT INTO shipments (order_id, carrier, tracking) VALUES (%s, %s, %s)", (order_id, carrier, tracking))
        elif action == "cancel":
            if status in ("shipped", "cancelled"):
                return jsonify(error="order can no longer be cancelled"), 409
            cur.execute("UPDATE orders SET status = 'cancelled' WHERE id = %s", (order_id,))
            cur.execute("UPDATE stock s SET qty = s.qty + l.qty FROM order_lines l WHERE l.order_id = %s AND s.sku = l.sku", (order_id,))
        else:
            return jsonify(error="unknown action"), 400
        cur.execute("INSERT INTO order_events (order_id, actor_id, action) VALUES (%s, %s, %s)", (order_id, actor, action))
        cur.execute("SELECT status FROM orders WHERE id = %s", (order_id,))
        new_status = cur.fetchone()[0]
    logger.info("order %s: %s -> %s by %s", order_id, status, new_status, actor)
    return jsonify(id=order_id, status=new_status)

def render_markdown(text):
    html = []
    in_list = False
    in_code = False
    for raw in text.splitlines():
        line = raw.rstrip()
        if line.startswith("```"):
            html.append("</pre>" if in_code else "<pre>")
            in_code = not in_code
            continue
        if in_code:
            html.append(line.replace("&", "&amp;").replace("<", "&lt;"))
            continue
        if line.startswith("- "):
            if not in_list:
                html.append("<ul>")
                in_list = True
            html.append("<li>" + line[2:] + "</li>")
            continue
        if in_list:
            html.append("</ul>")
            in_list = False
        if line.startswith("### "):
            html.append("<h3>" + line[4:] + "</h3>")
        elif line.startswith("## "):
            html.append("<h2>" + line[3:] + "</h2>")
        elif line.startswith("# "):
            html.append("<h1>" + line[2:] + "</h1>")
        elif line == "":
            html.append("")
        else:
            html.append("<p>" + line + "</p>")
    if in_list:
        html.append("</ul>")
    if in_code:
        html.append("</pre>")
    out = chr(10).join(html)
    for marker, tag in (("**", "strong"), ("_", "em")):
        parts = out.split(marker)
        out = parts[0]
        for i, part in enumerate(parts[1:], start=1):
            out += ("<" + tag + ">" if i % 2 else "</" + tag + ">") + part
    return out

def run_saved_report(conn, report_id, overrides=None):
    if overrides is not None and not isinstance(overrides, dict):
        raise TypeError("overrides must be a mapping")
    definition = conn.execute("SELECT table_name, columns, filters, sort, max_rows FROM saved_reports WHERE id = ?", (report_id,)).fetchone()
    if definition is None:
        raise LookupError(report_id)
    table, columns, filters, sort, max_rows = definition
    schema = REPORT_SCHEMA.get(table)
    if schema is None:
        raise ValueError("report uses an unsupported table")
    selected = [c for c in json.loads(columns) if c in schema["columns"]]
    if not selected:
        raise ValueError("report has no valid columns")
    clauses, params = [], []
    for item in json.loads(filters):
        name, op = item["column"], item["op"]
        if name not in schema["columns"] or op not in ("=", "<", ">", "<=", ">=", "!="):
            raise ValueError("report has an invalid filter")
        value = item["value"]
        if overrides and name in overrides:
            value = overrides[name]
        clauses.append(f"{name} {op} ?")
        params.append(value)
    order = ""
    if sort:
        column, _, direction = sort.partition(" ")
        if column not in schema["columns"] or direction.upper() not in ("", "ASC", "DESC"):
            raise ValueError("report has an invalid sort")
        order = f" ORDER BY {column} {direction.upper()}".rstrip()
    limit = max(1, min(int(max_rows or 100), 10000))
    sql_text = f"SELECT {', '.join(selected)} FROM {table}"
    if clauses:
        sql_text += " WHERE " + " AND ".join(clauses)
    sql_text += order + " LIMIT ?"
    params.append(limit)
    rows = conn.execute(sql_text, params).fetchall()
    conn.execute("UPDATE saved_reports SET last_run = datetime('now'), last_rows = ? WHERE id = ?", (len(rows), report_id))
    conn.commit()
    logger.info("report %s returned %d rows", report_id, len(rows))
    return {"columns": selected, "rows": rows, "truncated": len(rows) == limit}

