def upsert_readings(engine, device, readings):
    rows = [{"device": device, "at": r["at"], "value": r["value"]} for r in readings if r.get("value") is not None]
    if not rows:
        return {"written": 0, "skipped": len(readings)}
    stmt = pg_insert(device_readings).values(rows)
    stmt = stmt.on_conflict_do_update(
        index_elements=["device", "at"],
        set_={"value": stmt.excluded.value},
    )
    with engine.begin() as conn:
        conn.execute(stmt)
        conn.execute(update(devices).where(devices.c.name == device).values(last_seen=func.now()))
    return {"written": len(rows), "skipped": len(readings) - len(rows)}

def audit_page(conn, actor=None, action=None, page=1, size=50):
    offset = (max(page, 1) - 1) * size
    with conn.cursor() as cur:
        if actor and action:
            cur.execute("SELECT at, actor, action, target FROM audit WHERE actor = %s AND action = %s ORDER BY at DESC LIMIT %s OFFSET %s", (actor, action, size, offset))
        elif actor:
            cur.execute("SELECT at, actor, action, target FROM audit WHERE actor = %s ORDER BY at DESC LIMIT %s OFFSET %s", (actor, size, offset))
        elif action:
            cur.execute("SELECT at, actor, action, target FROM audit WHERE action = %s ORDER BY at DESC LIMIT %s OFFSET %s", (action, size, offset))
        else:
            cur.execute("SELECT at, actor, action, target FROM audit ORDER BY at DESC LIMIT %s OFFSET %s", (size, offset))
        rows = cur.fetchall()
    return [{"at": r[0].isoformat(), "actor": r[1], "action": r[2], "target": r[3]} for r in rows]

