def rate_product(user, product, stars):
    if not 1 <= stars <= 5:
        raise ValueError("stars must be between 1 and 5")
    rating, created = Rating.objects.update_or_create(user=user, product=product, defaults={"stars": stars})
    average = Rating.objects.filter(product=product).aggregate(avg=Avg("stars"))["avg"]
    Product.objects.filter(pk=product.pk).update(rating=average)
    return {"created": created, "average": round(average, 2)}

