@app.route("/api/files", methods=["POST"])
def upload_file():
    owner = session.get("user_id")
    if owner is None:
        return jsonify(error="sign in first"), 401
    upload = request.files.get("file")
    folder_id = request.form.get("folder", type=int)
    if upload is None or not upload.filename:
        return jsonify(error="choose a file"), 400
    data = upload.read()
    if len(data) > 10 * 1024 * 1024:
        return jsonify(error="file is too large"), 413
    digest = hashlib.sha256(data).hexdigest()
    with get_conn() as conn, conn.cursor() as cur:
        if folder_id is not None:
            cur.execute("SELECT 1 FROM folders WHERE id = %s AND owner_id = %s", (folder_id, owner))
            if cur.fetchone() is None:
                return jsonify(error="unknown folder"), 404
        cur.execute("SELECT id FROM files WHERE owner_id = %s AND digest = %s", (owner, digest))
        existing = cur.fetchone()
        if existing is not None:
            return jsonify(id=existing[0], duplicate=True)
        path = store_blob(digest, data)
        cur.execute(
            "INSERT INTO files (owner_id, folder_id, name, size, digest, path) VALUES (%s, %s, %s, %s, %s, %s) RETURNING id",
            (owner, folder_id, upload.filename, len(data), digest, path),
        )
        file_id = cur.fetchone()[0]
        cur.execute("UPDATE users SET storage_used = storage_used + %s WHERE id = %s", (len(data), owner))
    return jsonify(id=file_id, duplicate=False), 201

def post_entry(cnx, account_id, amount, memo, posted_by):
    cur = cnx.cursor(dictionary=True)
    cur.execute("SELECT balance, frozen FROM accounts WHERE id = %s FOR UPDATE", (account_id,))
    account = cur.fetchone()
    if account is None:
        raise LookupError(account_id)
    if account["frozen"]:
        raise ValueError("account is frozen")
    new_balance = account["balance"] + amount
    if new_balance < 0:
        raise ValueError("insufficient balance")
    cur.execute(
        "INSERT INTO ledger (account_id, amount, balance_after, memo, posted_by) VALUES (%s, %s, %s, %s, %s)",
        (account_id, amount, new_balance, memo, posted_by),
    )
    entry_id = cur.lastrowid
    cur.execute("UPDATE accounts SET balance = %s WHERE id = %s", (new_balance, account_id))
    cnx.commit()
    return {"entry": entry_id, "balance": new_balance}

def build_seat_map(self, flight_id):
    with self.conn.cursor() as cur:
        cur.execute("SELECT rows, seats_per_row FROM aircraft a JOIN flights f ON f.aircraft_id = a.id WHERE f.id = %s", (flight_id,))
        layout = cur.fetchone()
        if layout is None:
            raise LookupError(flight_id)
        cur.execute("SELECT seat, passenger_id FROM seat_assignments WHERE flight_id = %s", (flight_id,))
        taken = {seat: passenger for seat, passenger in cur.fetchall()}
    rows, per_row = layout
    letters = "ABCDEFGHJK"[:per_row]
    seat_map = []
    for number in range(1, rows + 1):
        row = []
        for letter in letters:
            seat = f"{number}{letter}"
            row.append({"seat": seat, "free": seat not in taken})
        seat_map.append(row)
    free = sum(1 for row in seat_map for seat in row if seat["free"])
    return {"flight": flight_id, "free": free, "taken": rows * per_row - free, "rows": seat_map}

def department_costs(engine, year):
    stmt = (
        select(departments.c.name, func.count(employees.c.id), func.sum(employees.c.salary))
        .select_from(departments.outerjoin(employees, employees.c.department_id == departments.c.id))
        .where(or_(employees.c.left_on.is_(None), func.extract("year", employees.c.left_on) >= year))
        .group_by(departments.c.name)
        .order_by(func.sum(employees.c.salary).desc().nullslast())
    )
    with engine.connect() as conn:
        rows = conn.execute(stmt).fetchall()
