def top_words(text, n=10, stop=frozenset({"the", "a", "of", "and", "to"})):
    counts = {}
    for raw in text.lower().split():
        word = raw.strip(".,;:!?()[]")
        if not word or word in stop:
            continue
        counts[word] = counts.get(word, 0) + 1
    ranked = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))
    return ranked[:n]

