def column_distribution(conn, table, column):
    with conn.cursor() as cur:
        query = sql.SQL("SELECT {col}, COUNT(*) FROM {tbl} GROUP BY {col} ORDER BY 2 DESC LIMIT 20").format(
            col=sql.Identifier(column), tbl=sql.Identifier(table)
