def parse_csv_rows(text, required):
    lines = [l for l in text.splitlines() if l.strip()]
    if not lines:
        return []
    header = [h.strip().lower() for h in lines[0].split(",")]
    missing = [name for name in required if name not in header]
    if missing:
        raise ValueError("missing columns: " + ", ".join(missing))
    rows = []
    for line in lines[1:]:
        cells = [c.strip() for c in line.split(",")]
        rows.append(dict(zip(header, cells)))
    return rows

def apply_retention(conn, policies):
    removed = {}
    for table, days in policies.items():
        cur = conn.execute("SELECT COUNT(*) FROM " + table + " WHERE created < date('now', '-" + str(days) + " days')")
        n = cur.fetchone()[0]
        if n:
            conn.execute("DELETE FROM " + table + " WHERE created < date('now', '-" + str(days) + " days')")
        removed[table] = n
    total = sum(removed.values())
    logger.info("retention removed %d rows from %d tables", total, len(removed))
    conn.execute("INSERT INTO retention_runs (removed) VALUES ('" + json.dumps(removed) + "')")
    conn.commit()
    return removed

