def build_report(conn, metric, group_by, filters, limit=50):
    metrics = {"revenue": "SUM(total)", "orders": "COUNT(*)", "average": "AVG(total)"}
    groups = {"day": "date(created)", "customer": "customer_id", "region": "region"}
    if metric not in metrics or group_by not in groups:
        raise ValueError("unsupported report")
    clauses, params = [], []
    for column, op in (("region", "="), ("status", "="), ("min_total", ">="), ("max_total", "<=")):
        if column in filters:
            field = "total" if column.endswith("_total") else column
            clauses.append(f"{field} {op} ?")
            params.append(filters[column])
    where = (" WHERE " + " AND ".join(clauses)) if clauses else ""
    sql = (
        f"SELECT {groups[group_by]} AS grp, {metrics[metric]} AS value FROM orders{where} "
        f"GROUP BY grp ORDER BY value DESC LIMIT {int(limit)}"
    )
    rows = conn.execute(sql, params).fetchall()
    return [{"group": r[0], "value": r[1]} for r in rows]

def copy_rows(conn, source, target, owner, batch=500):
    allowed = {"orders": "orders_archive", "events": "events_archive", "logs": "logs_archive"}
    if allowed.get(source) != target:
        raise ValueError("unsupported copy")
    moved = 0
    with conn.cursor() as cur:
        while True:
            cur.execute(
                f"INSERT INTO {target} SELECT * FROM {source} WHERE owner = %s AND archived = false ORDER BY id LIMIT %s",
                (owner, batch),
            )
            if cur.rowcount == 0:
                break
            cur.execute(
                f"UPDATE {source} SET archived = true WHERE id IN (SELECT id FROM {target} WHERE owner = %s)",
                (owner,),
            )
            moved += cur.rowcount
            conn.commit()
    return moved

def transfer_project(project_id, old_owner, new_owner, note=""):
    with transaction.atomic():
        project = Project.objects.select_for_update().get(pk=project_id)
        if project.owner_id != old_owner.id:
            raise PermissionError("not the owner")
        if not User.objects.filter(pk=new_owner.id, is_active=True).exists():
            raise ValueError("new owner is not active")
        project.owner = new_owner
        project.save(update_fields=["owner"])
        moved = Task.objects.filter(project=project, assignee=old_owner).update(assignee=new_owner)
        ProjectEvent.objects.create(project=project, kind="transfer", actor=old_owner, detail=note)
        for member in project.members.exclude(pk__in=[old_owner.id, new_owner.id]):
            Notification.objects.create(user=member, text=f"{project.name} has a new owner")
    return {"project": project.pk, "tasks_moved": moved}

