    if filters.get("customer"):
        joins.append("JOIN customers c ON c.id = o.customer_id")
        where.append("c.name LIKE ?")
        args.append("%" + filters["customer"] + "%")
    if filters.get("region"):
        where.append("o.region = ?")
        args.append(filters["region"])
    if filters.get("from"):
        where.append("o.created >= ?")
        args.append(filters["from"])
    if filters.get("to"):
        where.append("o.created < ?")
        args.append(filters["to"])
    if filters.get("min_total"):
        where.append("o.total >= ?")
        args.append(float(filters["min_total"]))
    if joins:
        sql += " " + " ".join(joins)
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " GROUP BY bucket ORDER BY revenue DESC"
    count_sql = "SELECT COUNT(*) FROM (" + sql + ")"
    total_groups = conn.execute(count_sql, args).fetchone()[0]
    sql += " LIMIT " + str(page_size) + " OFFSET " + str((page - 1) * page_size)
    rows = conn.execute(sql, args).fetchall()
    revenue = sum(r[2] or 0 for r in rows)
    result = []
    for bucket, orders, value in rows:
        share = (value or 0) / revenue if revenue else 0.0
        result.append({"bucket": bucket, "orders": orders, "revenue": value, "share": round(share, 4)})
    return {"groups": total_groups, "page": page, "rows": result}

