def export_table(conn, name, columns):
    tables = {"customers": ("id", "name", "email"), "products": ("sku", "name", "price")}
    if name not in tables:
        raise ValueError(name)
    allowed = tables[name]
    cols = [c for c in columns if c in allowed] or list(allowed)
    cur = conn.cursor()
    cur.execute(f"SELECT {', '.join(cols)} FROM {name} ORDER BY {cols[0]}")
    rows = cur.fetchall()
    return {"columns": cols, "rows": rows}

