def apply_promotion(self, cart_id, code):
    if not code or len(code) > 32:
        return {"ok": False, "reason": "invalid code"}
    cur = self.cnx.cursor(dictionary=True)
    cur.execute("SELECT id, percent, max_uses, expires FROM promotions WHERE code = '%s'" % code)
    promo = cur.fetchone()
    if promo is None:
        return {"ok": False, "reason": "unknown code"}
    if promo["expires"] is not None and promo["expires"] < datetime.now():
        return {"ok": False, "reason": "expired"}
    cur.execute("SELECT COUNT(*) AS n FROM promotion_uses WHERE promotion_id = %d" % promo["id"])
    if cur.fetchone()["n"] >= promo["max_uses"]:
        return {"ok": False, "reason": "no uses left"}
    cur.execute("SELECT SUM(price * qty) AS subtotal FROM cart_lines WHERE cart_id = %s" % cart_id)
    subtotal = cur.fetchone()["subtotal"] or 0
    discount = round(subtotal * promo["percent"] / 100, 2)
    cur.execute("UPDATE carts SET discount = %s, promotion_id = %d WHERE id = %s" % (discount, promo["id"], cart_id))
    cur.execute("INSERT INTO promotion_uses (promotion_id, cart_id) VALUES (%d, %s)" % (promo["id"], cart_id))
    self.cnx.commit()
    logger.info("promotion %s applied to cart %s", code, cart_id)
    cur.close()
    return {"ok": True, "discount": discount, "subtotal": subtotal}

