def export_rows(conn, table, columns, filters, order_by=None, limit=1000):
    schema = {
        "customers": {"id", "name", "email", "city", "created"},
        "orders": {"id", "customer_id", "total", "status", "created"},
        "products": {"sku", "name", "price", "category"},
    }
    if table not in schema:
        raise ValueError("unknown table")
    allowed = schema[table]
    selected = [c for c in columns if c in allowed] or sorted(allowed)
    clauses, params = [], []
    for column, value in filters.items():
        if column not in allowed:
            raise ValueError("cannot filter on " + column)
        if isinstance(value, (list, tuple)):
            clauses.append(f"{column} IN ({', '.join('?' for _ in value)})")
            params.extend(value)
        else:
            clauses.append(f"{column} = ?")
            params.append(value)
    sql = f"SELECT {', '.join(selected)} FROM {table}"
    if clauses:
        sql += " WHERE " + " AND ".join(clauses)
    if order_by:
        if order_by not in allowed:
            raise ValueError("cannot order by " + order_by)
        sql += f" ORDER BY {order_by}"
    sql += " LIMIT ?"
    params.append(int(limit))
    rows = conn.execute(sql, params).fetchall()
    return {"columns": selected, "rows": rows}

def prune_tenant(conn, tenant, tables, keep_days=90, dry_run=False):
    prunable = {"events": "created_at", "sessions": "last_seen", "audit": "at", "uploads": "uploaded_at"}
    unknown = [t for t in tables if t not in prunable]
    if unknown:
        raise ValueError("cannot prune: " + ", ".join(unknown))
    keep_days = int(keep_days)
    report = {}
    with conn.cursor() as cur:
        for table in tables:
            column = prunable[table]
            cur.execute(
                f"SELECT COUNT(*) FROM {table} WHERE tenant = %s AND {column} < now() - make_interval(days => %s)",
                (tenant, keep_days),
            )
            count = cur.fetchone()[0]
            report[table] = count
            if count and not dry_run:
                cur.execute(
                    f"DELETE FROM {table} WHERE tenant = %s AND {column} < now() - make_interval(days => %s)",
                    (tenant, keep_days),
                )
        if dry_run:
            conn.rollback()
        else:
            cur.execute("INSERT INTO prune_log (tenant, report) VALUES (%s, %s)", (tenant, json.dumps(report)))
            conn.commit()
    return report

