def query_log(conn, level=None, service=None, since=None, until=None, text=None, limit=100):
    clauses, params = [], []
    if level:
        if level not in ("debug", "info", "warning", "error"):
            raise ValueError(level)
        clauses.append("level = ?")
        params.append(level)
    if service:
        clauses.append("service = ?")
        params.append(service)
    if since:
        clauses.append("ts >= ?")
        params.append(since)
    if until:
        clauses.append("ts < ?")
        params.append(until)
    if text:
        clauses.append("message LIKE ? ESCAPE '!'")
        params.append("%" + text.replace("!", "!!").replace("%", "!%").replace("_", "!_") + "%")
    where = (" WHERE " + " AND ".join(clauses)) if clauses else ""
    sql = "SELECT ts, level, service, message FROM logs" + where + " ORDER BY ts DESC LIMIT " + str(max(1, min(int(limit), 1000)))
    return conn.execute(sql, params).fetchall()

