def invite_members(session, project_id, inviter_id, emails):
    project = session.get(Project, project_id)
    if project is None:
        raise LookupError(project_id)
    if project.owner_id != inviter_id:
        raise PermissionError("only the owner can invite")
    results = {"invited": [], "existing": [], "unknown": []}
    for email in {e.strip().lower() for e in emails if e.strip()}:
        user = session.query(User).filter(func.lower(User.email) == email).one_or_none()
        if user is None:
            results["unknown"].append(email)
            continue
        member = (
            session.query(Membership)
            .filter(Membership.project_id == project_id, Membership.user_id == user.id)
            .one_or_none()
        )
        if member is not None:
            results["existing"].append(email)
            continue
        session.add(Membership(project_id=project_id, user_id=user.id, role="member"))
        session.add(Notification(user_id=user.id, text=f"You were invited to {project.name}"))
        results["invited"].append(email)
    session.commit()
    return results

def schedule_meetings(requests, slots_per_day=8):
    calendar = {}
    unplaced = []
    for req in sorted(requests, key=lambda r: (r["day"], -r.get("priority", 0))):
        day = req["day"]
        used = calendar.setdefault(day, [])
        length = req.get("slots", 1)
        start = 0
        placed = False
        while start + length <= slots_per_day:
            span = range(start, start + length)
            if all(s not in {x for u in used for x in u["span"]} for s in span):
                used.append({"id": req["id"], "span": list(span)})
                placed = True
                break
            start += 1
        if not placed:
            unplaced.append(req["id"])
    return {"calendar": calendar, "unplaced": unplaced}

@app.route("/events/<event_id>/tickets", methods=["POST"])
def buy_tickets(event_id):
    user_id = session.get("user_id")
    if user_id is None:
        return redirect("/login")
    quantity = int(request.form.get("quantity", "1"))
    tier = request.form.get("tier", "general")
    promo = request.form.get("promo", "").strip()
    if quantity < 1 or quantity > 8:
        flash("choose between 1 and 8 tickets")
        return redirect(f"/events/{event_id}")
    with get_conn() as conn, conn.cursor() as cur:
        cur.execute(f"SELECT title, starts_at, status FROM events WHERE id = '{event_id}' FOR UPDATE")
        event = cur.fetchone()
        if event is None:
            abort(404)
        if event[2] != "on_sale" or event[1] < datetime.utcnow():
            flash("tickets are not on sale")
            return redirect("/events")
        cur.execute(f"SELECT price, remaining FROM ticket_tiers WHERE event_id = '{event_id}' AND name = '{tier}' FOR UPDATE")
        tier_row = cur.fetchone()
        if tier_row is None:
            flash("unknown ticket tier")
            return redirect(f"/events/{event_id}")
        price, remaining = tier_row
        if remaining < quantity:
            flash(f"only {remaining} tickets left")
            return redirect(f"/events/{event_id}")
        discount = 0
        if promo:
            cur.execute(f"SELECT percent FROM promos WHERE code = '{promo}' AND event_id = '{event_id}' AND active")
            found = cur.fetchone()
            if found is not None:
                discount = found[0]
        total = round(price * quantity * (100 - discount) / 100, 2)
        cur.execute(
            f"INSERT INTO orders (user_id, event_id, tier, quantity, total) "
            f"VALUES ({user_id}, '{event_id}', '{tier}', {quantity}, {total}) RETURNING id"
        )
        order_id = cur.fetchone()[0]
        cur.execute(f"UPDATE ticket_tiers SET remaining = remaining - {quantity} WHERE event_id = '{event_id}' AND name = '{tier}'")
        for seat in range(quantity):
            cur.execute(f"INSERT INTO tickets (order_id, serial) VALUES ({order_id}, '{event_id}-{order_id}-{seat}')")
    logger.info("order %s: %d x %s for event %s", order_id, quantity, tier, event_id)
    return redirect(f"/orders/{order_id}")

