def usage_for_period(self, account, start, end, kinds):
    kind_list = ", ".join("'" + k + "'" for k in kinds)
    sql = "SELECT kind, SUM(units) FROM usage WHERE account = '{a}' AND day BETWEEN '{s}' AND '{e}' AND kind IN ({k}) GROUP BY kind"
