                        else True
                    ),
                ),
                isouter=True,
            )
            .where(DagScheduleAssetReference.dag_id == dag_id, AssetModel.active.has())
            .group_by(AssetModel.id, AssetModel.uri)
            .order_by(AssetModel.uri)
        )
    ]
    data = {"asset_expression": dag_model.asset_expression, "events": events}
    return data

